WITH parsed AS (SELECT id, customer_id, coupon_codes, ship_to, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, COALESCE(attributes['gift'], 'unknown') AS gift_or_default FROM carts) SELECT customer_id, CASE WHEN weight_kg >= 4.1 THEN 'HIGH' ELSE 'LOW' END AS weight_kg_tier, APPROX_PERCENTILE(weight_kg, ARRAY(0.25, 0.5, 0.75)) AS weight_kg_quartiles, ROUND(AVG(weight_kg), 2) AS avg_weight_kg, COUNT(DISTINCT customer_id) AS distinct_customer_ids, GROUPING(customer_id) AS grouping_level FROM parsed GROUP BY CUBE (customer_id, CASE WHEN weight_kg >= 4.1 THEN 'HIGH' ELSE 'LOW' END);
